using System.IO.Ports;
namespace ESD.Infrastructure;
public sealed class SerialTransport:IDisposable{SerialPort? p;public event EventHandler<byte[]>? Data;public event EventHandler<string>? Error;public bool IsOpen=>p?.IsOpen==true;public void Open(string n,int baud){Close();p=new SerialPort(n,baud,Parity.None,8,StopBits.One){ReadTimeout=500,WriteTimeout=500};p.DataReceived+=Rx;p.Open();}void Rx(object? s,SerialDataReceivedEventArgs e){try{if(p==null)return;var a=new byte[p.BytesToRead];p.Read(a,0,a.Length);if(a.Length>0)Data?.Invoke(this,a);}catch(Exception x){Error?.Invoke(this,x.Message);}}public void Write(byte[] b){if(!IsOpen)throw new InvalidOperationException("Serial port is not connected.");p!.Write(b,0,b.Length);}public void Close(){if(p==null)return;try{p.DataReceived-=Rx;p.Close();p.Dispose();}finally{p=null;}}public static string[] Ports()=>SerialPort.GetPortNames().OrderBy(x=>x).ToArray();public void Dispose()=>Close();}
